query Query($inventoryNumber: String!, $masterInventoryNumber: String!) {
  inventory(where: {number:{_eq:$inventoryNumber} active:{_eq:true}}) {
    edges {
      node {
        id
				active
        barcode
        number
        trackingNumber
        location {
          id
          name
          locationType {
            id
            name

            quarantine
          }
        }
        inventoryStatus {
          id
          name
          active
          suspect
          mergePrevent
          movePrevent
          splitPrevent
        }
        quantity {
          value
          unitId
        }
        weightUnit {
          id
          code
        }
        grossWeight
        netWeight
        tareWeight
        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            mergePrevent
            movePrevent

          }
        }
        productStrategyProcess {
          id
          code          
          unitWeight
          productStrategy {
            id
            code
            name
            product {
              id
              code
              name
            }
          }
        }
      }
    }
  }
  productionSetupMaterial(where:{inventory:{number:{_eq:$inventoryNumber}}}) {
    edges {
      node {
        id
        number
        productionSetup {
          id
          workcenter {
            name
          }
        }
      }
    }
  }
  masterInventory(where:{number:{_eq:$masterInventoryNumber}}) {
    edges {
      node {
        id
        number
      }
    }
  }  
  transactionType(where:{inventoryAdjustment:{_eq:true}} first:1) {
    edges {
      node {
        id
      }
    }
  }
}

